// Access layer for the guides and blog posts.
//
// Every article exists once, as a source file:
//
//   content/<locale>/guides/<slug>.html
//   content/<locale>/blog/<slug>.html
//
// Those are what you edit. Nothing copies them anywhere; the bodies below are
// the same files, rewritten for the site as Vite reads them (see
// scripts/vite-plugin-articles.mjs) and split into one lazy chunk per article.
//
// The manifests are generated from those same files by `npm run build:content`,
// which lifts each article's <h1> and intro out into metadata so the card grids
// and meta tags don't have to load every body. English is the base manifest; a
// locale manifest carries only the translated fields (title, description, tag,
// readTime, words) keyed by type+slug, with everything else (path, images,
// order) inherited from English so it never drifts between locales.

import manifestEn from './manifest.json';

// Locale overlays are picked up from disk rather than imported one by one, so
// `npm run build:content` writing a new manifest.<lang>.json is all it takes
// for that locale's cards and meta tags to start using translated copy. Eager
// glob, so these stay in the main bundle alongside the English manifest.
// The inlined English homepage (import.meta.env.EDB_HOME) needs neither the
// overlays nor the article bodies, so its build leaves them out.
const overlaysByLocale = Object.fromEntries(
  Object.entries(
    import.meta.env.EDB_HOME ? {} : import.meta.glob('./manifest.*.json', { eager: true, import: 'default' })
  ).map(([path, overlay]) => [/manifest\.([^.]+)\.json$/.exec(path)[1], overlay])
);

const bodies = import.meta.env.EDB_HOME
  ? {}
  : import.meta.glob('../../content/*/*/*.html', { query: '?raw', import: 'default' });

const manifestCache = new Map();

// Every article carries `href`: its own URL in `lang` when that translation is
// published on the site (content/translations.json), else the English URL, since
// the site has no page for it in that language. `inApp` also merges translations
// that are not published, for the app's Help page, which shows them in place.
function getManifest(lang, { inApp = false } = {}) {
  if (lang === 'en' || !overlaysByLocale[lang]) return manifestEn.map((a) => ({ ...a, href: a.path }));
  const cacheKey = `${lang}:${inApp}`;
  if (manifestCache.has(cacheKey)) return manifestCache.get(cacheKey);
  const overlay = new Map(overlaysByLocale[lang].map((a) => [`${a.type}:${a.slug}`, a]));
  const merged = manifestEn.map((a) => {
    const tr = overlay.get(`${a.type}:${a.slug}`);
    const href = tr?.published ? `/${lang}${a.path}` : a.path;
    return tr && (tr.published || inApp) ? { ...a, ...tr, href } : { ...a, href };
  });
  manifestCache.set(cacheKey, merged);
  return merged;
}

export const allArticles = (lang = 'en', opts) => getManifest(lang, opts);
export const guides = (lang = 'en', opts) => getManifest(lang, opts).filter((a) => a.type === 'guide');
export const posts = (lang = 'en', opts) => getManifest(lang, opts).filter((a) => a.type === 'blog');

export const findArticle = (type, slug, lang = 'en', opts) =>
  getManifest(lang, opts).find((a) => a.type === type && a.slug === slug) || null;

/** Slugs that render through the generic <Article> page rather than a hand-written one. */
export const importedSlugs = (type, lang = 'en') =>
  getManifest(lang).filter((a) => a.type === type && a.imported).map((a) => a.slug);

/** The languages an article is published in on the site (English first), from
 *  content/translations.json via the manifests. The page's hreflang tags and the
 *  language switcher offer exactly these. */
export function articleLanguages(type, slug) {
  const published = Object.entries(overlaysByLocale)
    .filter(([, overlay]) => overlay.some((a) => a.type === type && a.slug === slug && a.published))
    .map(([lang]) => lang)
    .sort();
  return ['en', ...published];
}

/** articleLanguages() for a pathname, or null when it is not an article page. */
export function pathArticleLanguages(pathname) {
  const m = /^\/(guides|blog)\/([a-z0-9-]+)\/?$/.exec(pathname);
  if (!m) return null;
  const type = m[1] === 'guides' ? 'guide' : 'blog';
  return manifestEn.some((a) => a.type === type && a.slug === m[2]) ? articleLanguages(type, m[2]) : null;
}

/** Resolves to the article's HTML body, falling back to English, or null. */
export function loadArticleBody(type, slug, lang = 'en') {
  const dir = type === 'guide' ? 'guides' : 'blog';
  const at = (l) => bodies[`../../content/${l}/${dir}/${slug}.html`];
  const load = at(lang) || at('en');
  return load ? load() : Promise.resolve(null);
}
